    POOL_V1_PAIR_POSEIDON_BLOCKS + POOL_V1_PAIR_PATH_AUX_BLOCKS + POOL_V1_PAIR_VALUE_AUX_BLOCKS;
pub const POOL_V1_PAIR_ALLOCATED_ROWS: usize =
